function validate([nums, left, right]) {
  if (!Array.isArray(nums) || nums.length < 1 || nums.length > 100000) return 'nums needs 1 to 100000 values.';
  if (nums.some(v => !Number.isInteger(v) || v < 0 || v > 1e9)) return 'Each value of nums is an integer from 0 to 10^9.';
  if (!Number.isInteger(left) || !Number.isInteger(right) || left < 0 || right > 1e9 || left > right) return 'Need 0 <= left <= right <= 10^9.';
  let count = 0, tooBig = -1, inRange = -1;
  for (let i = 0; i < nums.length; i++) {
    if (nums[i] > right) tooBig = i;
    if (nums[i] >= left && nums[i] <= right) inRange = i;
    if (inRange > tooBig) count += inRange - tooBig;
  }
  if (count > 2147483647) return 'The answer must fit in a 32-bit signed integer.';
  return null;
}

