  let count = 0;
  let lastTooBig = -1;
  let lastInRange = -1;

  for (let end = 0; end < nums.length; end++) {
    if (nums[end] > right) {
      lastTooBig = end;
    }
    if (nums[end] >= left && nums[end] <= right) {
      lastInRange = end;
    }
    if (lastInRange > lastTooBig) {
      count += lastInRange - lastTooBig;
    }
  }
  return count;
}

